"use client";

import { useEffect, useState } from "react";
import { CalendarDays, MapPin, Flag } from "lucide-react";

interface GrandPrix {
id: string;

sponsored_name: string;
name: string;
additional_name: string;
short_name: string;

date_start: string;
date_end: string;

status: string;

country: {
iso: string;
name: string;
region_iso: string;
};

circuit: {
id: string;
name: string;
place: string;
nation: string;
};
}

interface ApiResponse {
data: GrandPrix;
}

function formatDate(date: string) {
return new Intl.DateTimeFormat("es-ES", {
day: "numeric",
month: "long",
year: "numeric",
}).format(new Date(`${date}T12:00:00`));
}

export function NextGrandPrix() {
const [grandPrix, setGrandPrix] =
useState<GrandPrix | null>(null);

const [loading, setLoading] =
useState(true);

const [error, setError] =
useState<string | null>(null);

useEffect(() => {
async function loadGrandPrix() {
try {
const response =
await fetch("/api/next-gp");

    if (!response.ok) {
      throw new Error(
        "No se pudo cargar el Gran Premio"
      );
    }

    const result: ApiResponse =
      await response.json();

    setGrandPrix(result.data);
  } catch (error) {
    console.error(error);

    setError(
      "No se ha podido cargar la información del próximo GP"
    );
  } finally {
    setLoading(false);
  }
}

loadGrandPrix();    

}, []);

if (loading) {
return ( <section className="card p-8 md:p-10"> <p className="text-sm text-zinc-500">
Cargando información del Gran Premio... </p> </section>
);
}

if (error || !grandPrix) {
return ( <section className="card p-8 md:p-10"> <p className="text-red-400">
{error || "No hay información disponible"} </p> </section>
);
}

return ( <article className="card relative overflow-hidden p-7 md:p-10"> <div className="absolute inset-0 bg-gradient-to-br from-red-950/40 via-transparent to-transparent" />

  <div className="relative">
    <div className="mb-10 flex items-center justify-between">
      <span className="rounded-full border border-red-500/30 bg-red-500/10 px-3 py-1 text-xs font-bold text-red-400">
        {grandPrix.short_name}
      </span>

      <CalendarDays className="text-zinc-500" />
    </div>

    <p className="text-xs uppercase tracking-[.22em] text-red-500">
      Próximo Gran Premio
    </p>

    <h2 className="mt-4 max-w-2xl text-3xl font-black md:text-5xl">
      {grandPrix.sponsored_name || grandPrix.name}
    </h2>

    <div className="mt-6 grid gap-4 md:grid-cols-2">
      <div className="flex items-start gap-3 text-zinc-400">
        <MapPin
          size={20}
          className="mt-0.5 shrink-0 text-red-500"
        />

        <div>
          <p className="font-medium text-zinc-200">
            {grandPrix.circuit.name}
          </p>

          <p className="text-sm text-zinc-500">
            {grandPrix.circuit.place},{" "}
            {grandPrix.country.name}
          </p>
        </div>
      </div>

      <div className="flex items-start gap-3 text-zinc-400">
        <CalendarDays
          size={20}
          className="mt-0.5 shrink-0 text-red-500"
        />

        <div>
          <p className="font-medium text-zinc-200">
            {formatDate(grandPrix.date_start)}
          </p>

          <p className="text-sm text-zinc-500">
            Hasta {formatDate(grandPrix.date_end)}
          </p>
        </div>
      </div>
    </div>

    <div className="mt-6 flex items-center gap-2 text-sm text-zinc-500">
      <Flag size={15} />

      <span>
        {grandPrix.country.iso} ·{" "}
        {grandPrix.additional_name}
      </span>
    </div>

    <div className="mt-10 flex flex-wrap gap-3">
      <button className="rounded-lg bg-red-600 px-5 py-3 text-sm font-bold transition hover:bg-red-500">
        Ver evento
      </button>

      <button className="rounded-lg border border-white/15 px-5 py-3 text-sm font-bold transition hover:bg-white/5">
        Ver calendario
      </button>
    </div>
  </div>
</article>

);
}
